  if (m(/^(?:单数|奇数)回合(?:时|结束时|结束后)?$/)) return { turnParity: "odd" };
  if (m(/^偶数回合(?:时|结束时|结束后)?$/)) return { turnParity: "even" };
  // "对手最大体力高于自身"（最大体力比较谓词）
  if (m(/^(?:对手|对方|敌方)(?:的)?最大体力(?:值)?(?:高于|大于|超过)(?:自身|自己)$/)) return { foeMaxHpAboveSelf: true };
  if (m(/^(?:自身|自己)(?:的)?最大体力(?:值)?(?:低于|小于|少于)(?:对手|对方|敌方)$/)) return { foeMaxHpAboveSelf: true };
  // 天敌谓词（"对手为自身天敌"/"对手是自身天敌"——foeCountersUs 已有运行时支持）
  if (m(/^(?:对手|对方|敌方)(?:为|是|属于)(?:自身|自己)?天敌$/)) return { foeCountersUs: true };
  if (m(/^(?:自身|自己|我)(?:为|是|属于)(?:对手|对方|敌方)?天敌$/)) return { weCounterFoe: true };
  if (m(/^(?:自身|自己)?未受到攻击$/) ?? m(/^(?:自身|自己)?未受攻击$/) ?? m(/^(?:本|当)?回合?未受到(?:攻击|攻击伤害|伤害)$/) ?? m(/^(?:自身|自己)?未受到(?:攻击)?伤害$/)) return { prevTakenZero: true };
  // 阶段/回合类谓词——须在"处于X"具名印记兜底之前（否则"自身处于能力强化状态"被吞成名为"能力强化"的印记）
  if (m(/^(?:自身|自己)?已?处于(?:(?:能力)+(?:提升|增强|强化|上升)|强化|提升|增益)(?:的)?状态?$/)) return { selfStageUp: true };
  if (m(/^(?:自身|自己)?能力(?:得到|获得|有所|受到)?(?:提升|增强|强化|上升)$/)) return { selfStageUp: true }; // "自身能力得到提升时"——已获提升守卫近似
  if (m(/^(?:对手|对方|敌方)能力(?:得到|获得|有所|受到)?(?:提升|增强|强化|上升)$/)) return { foeStageUp: true };
  if (m(/^(?:对手|对方|敌方)已?处于(?:(?:能力)+(?:提升|增强|强化|上升)|强化|提升|增益)(?:的)?状态?$/)) return { foeStageUp: true };
  if (m(/^(?:自身|自己)?(?:不|未)已?处于(?:(?:能力)+(?:提升|增强|强化|上升)|强化|提升)(?:的)?状态?$/)) return { not: { selfStageUp: true } };
  if (m(/^(?:对手|对方|敌方)(?:不|未)已?处于(?:(?:能力)+(?:提升|增强|强化|上升)|强化|提升)(?:的)?状态?$/)) return { not: { foeStageUp: true } };
  // "<stat>处于提升/强化状态"——单维 stage 门（"速度处于提升状态时"→selfStatAtLeast{spd,1}；"对手攻击处于提升"→statAtLeast）
  if ((mm = m(new RegExp(`^(?:自身|自己)?(?:的)?(${STAT_RE}|命中|暴击)(?:能力)?已?处于(?:能力)?(?:提升|增强|强化|上升)(?:的)?状态?$`)))) {
    const st = mm[1] === "命中" ? "acc" : mm[1] === "暴击" ? "crt" : STATS[mm[1]];
    if (st !== undefined) return { selfStatAtLeast: { stat: st, stage: 1 } };
  }
  if ((mm = m(new RegExp(`^(?:对手|对方|敌方)(?:的)?(${STAT_RE}|命中|暴击)(?:能力)?已?处于(?:能力)?(?:提升|增强|强化|上升)(?:的)?状态?$`)))) {
    const st = mm[1] === "命中" ? "acc" : mm[1] === "暴击" ? "crt" : STATS[mm[1]];
    if (st !== undefined) return { statAtLeast: { stat: st, stage: 1 } };
  }
  // 复合态谓词（"处于能力提升或下降状态"/"处于能力下降或异常状态"——整组 or 复合，印记兜底不认"或"连词）
  if (m(/^(?:自身|自己)?处于能力(?:提升|增强|强化)(?:或|或者)(?:能力)?下降(?:的)?状态?$/)) return { or: [{ selfStageUp: true }, { selfStageDown: true }] };
  if (m(/^(?:对手|对方|敌方)处于能力(?:提升|增强|强化)(?:或|或者)(?:能力)?下降(?:的)?状态?$/)) return { or: [{ foeStageUp: true }, { foeStageDown: true }] };
  if (m(/^(?:自身|自己)?处于能力下降或(?:者)?异常(?:的)?状态?$/)) return { or: [{ selfStageDown: true }, { selfStatused: true }] };
  if (m(/^(?:对手|对方|敌方)处于能力下降或(?:者)?异常(?:的)?状态?$/)) return { or: [{ foeStageDown: true }, { foeStatused: true }] };
  // "对手处于回合类效果"→foeHasTimed（负向谓词 foeNoTimedFx 已有，正向由本行接）
  if (m(/^(?:对手|对方|敌方)(?:存在|处于)回合类效果(?:中|状态)?$/)) return { foeHasTimed: true };
  // 护盾消耗量谓词（"若消耗的护盾值大于300"——须在 markCountAtLeast 之前，否则"消耗的护盾值"被当印记名）
  if ((mm = m(/^消耗的护[盾罩]值?(?:若)?(?:高于|大于|超过)(\d+)(?:点)?$/))) return { shieldConsumedAbove: num(mm[1]) };
  if ((mm = m(/^消耗的护[盾罩]值?(?:若)?(?:低于|小于)(\d+)(?:点)?$/))) return { shieldConsumedBelow: num(mm[1]) };
  // "[actor]X大于N个/N层"——具名印记阈值谓词（"风龙结大于500个"/"自身风龙结大于500个"→markCountAtLeast{mark,n,on}）
  // "[actor]X层数大于等于N层"变体（"蓄力层数大于等于6层"——`层数`/`≥`词形；"对手被施加的诡符数量达到4道"——施加语态+道量词）
  if ((mm = m(/^(自身|自己|对手|对方|敌方)?(?:的|被施加的?)?([一-龥]{2,8})(?:数量|层数|的层数)?(?:大于等于|>=|≥|大于|超过|不少于|不低于|达到|不小于)(\d+)(?:个|层|枚|道)?$/))) {
    const mk3 = mm[2].replace(/(?:层数|数量)$/, "").replace(/的$/, "");
    // 排除伤害/承伤谓词碎片（"受伤不超过250"→mk3="受伤不"——否定副词泄入印记名）
    if (!/^(异常状态|异常|弱化|能力提升|能力下降|强化|烧伤|麻痹|害怕|睡眠|中毒|冻伤|冰封|混乱|失明|石化|束缚|瘫痪|流血|沉默|臣服|疲惫|诅咒|护盾|护罩|回合|满体力|体力|HP|等级|先制)$/u.test(mk3) && !/伤害|受伤|受击|体力|生命|血量|HP|PP|pp|攻击|防御|特攻|特防|速度|命中|威力|等级|先制|回合|伤害值|恢复|减少|提升|提高|增加|受到|造成|自身|对手|对方|敌方|不$|未$/u.test(mk3)) return { markCountAtLeast: { mark: mk3, n: num(mm[3]), on: /对手|对方|敌方/.test(mm[1] ?? "") ? "foe" : "self" } };
  }
  // ── 双防/双攻/全属性提升组合（"不处于双防能力提升状态"→not or；肯定形→or 任一；先于通用名宿谓词） ──
  if ((mm = m(/^(?:自身|自己)?(不处于|未处于|没有|处于|存在)(双防|防御和特防|双攻|攻击和特攻|全属性|所有属性|所有能力)(?:能力)?(?:提升|强化|上升)(?:状态)?$/))) {
    const neg = /不处于|未处于|没有/.test(mm[1]);
    const pair = /双攻|攻击和特攻/.test(mm[2]) ? ["atk", "spa"] : /全属性|所有属性|所有能力/.test(mm[2]) ? ["atk", "def", "spa", "sdf", "spd"] : ["def", "sdf"];
    const or = { or: pair.map((st) => ({ selfStatAtLeast: { stat: st, stage: 1 } })) };
    return neg ? { not: or } : or;
  }
  // 对手侧镜像（"攻击时对手不处于双防能力提升状态则X"——statAtLeast 为对手维度谓词）
  if ((mm = m(/^(?:对手|对方|敌方)(不处于|未处于|没有|处于|存在)(双防|防御和特防|双攻|攻击和特攻|全属性|所有属性|所有能力)(?:能力)?(?:提升|强化|上升)(?:状态)?$/))) {
    const neg = /不处于|未处于|没有/.test(mm[1]);
    const pair = /双攻|攻击和特攻/.test(mm[2]) ? ["atk", "spa"] : /全属性|所有属性|所有能力/.test(mm[2]) ? ["atk", "def", "spa", "sdf", "spd"] : ["def", "sdf"];
    const or = { or: pair.map((st) => ({ statAtLeast: { stat: st, stage: 1 } })) };
    return neg ? { not: or } : or;
  }
  // "处于/不处于 X"——自定义命名印记谓词（"对手处于痴愚"→markCountAtLeast；已知状态由前置谓词先匹配）
  if ((mm = m(/^(对手|对方|敌方|自身|自己)?(?:不|未)已?处于([一-龥]{2,8})(?:状态)?$/))) {
    const mk2 = mm[2].replace(/状态$/, "");
    const on = /自身|自己/.test(mm[1] ?? "") ? "self" : "foe";
    if (AILMENTS[mk2] !== undefined) return { not: { [on === "self" ? "selfHas" : "foeHas"]: AILMENTS[mk2] } };
    if (!/^(异常状态|异常|弱化|能力提升|能力下降|强化|烧伤|麻痹|害怕|睡眠|中毒|冻伤|冰封|混乱|失明|石化|束缚|瘫痪|流血|沉默|臣服|疲惫|诅咒|护盾|护罩|回合|满体力)$/.test(mk2) && !/能力(?:提升|强化|下降|弱化)$/.test(mk2)) return { not: { markCountAtLeast: { mark: mk2, n: 1, on } } };
  }
  // "双方任意一方处于/不处于X" → or 复合（self∨foe）
  if ((mm = m(/^双方(?:任意)?一方不处于([一-龥]{2,8})(?:状态)?$/))) {
    const mk0 = mm[1].replace(/状态$/, "");
    const key = AILMENTS[mk0] ?? (/^护[盾罩]$/.test(mk0) ? "shield" : mk0);
    return { not: { or: [{ selfHas: key }, { foeHas: key }] } };
  }
  if ((mm = m(/^双方(?:任意)?一方处于([一-龥]{2,8})(?:状态)?$/))) {
    const mk0 = mm[1].replace(/状态$/, "");
    const key = AILMENTS[mk0] ?? (/^护[盾罩]$/.test(mk0) ? "shield" : mk0);
    return { or: [{ selfHas: key }, { foeHas: key }] };
  }
  if ((mm = m(/^(对手|对方|敌方|自身|自己)?已?处于([一-龥]{2,8})(?:状态)?$/))) {
    const mk = mm[2].replace(/状态$/, "").replace(new RegExp(`(${AIL_RE})下$`), "$1");
    const on = /自身|自己/.test(mm[1] ?? "") ? "self" : "foe";
    if (AILMENTS[mk] !== undefined) return { [on === "self" ? "selfHas" : "foeHas"]: AILMENTS[mk] };
    // 任意异常不是印记。标成 mark 会拆掉「处于任意异常状态时…」，已有 drainIf 规则看不到整句。
    if (!/^(异常状态|异常|任意异常|弱化|能力提升|能力下降|强化|烧伤|麻痹|害怕|睡眠|中毒|冻伤|冰封|混乱|失明|石化|束缚|瘫痪|流血|沉默|臣服|疲惫|诅咒|护盾|护罩|回合|满体力)$/.test(mk)) return { markCountAtLeast: { mark: mk, n: 1, on } };
  }
  // "对方精灵均没有X"/"没有X"——印记缺失谓词
  // "没有将X击败"是把字动作谓词（延迟同归于尽的触发条件），不是印记缺失——放走由 doom 规则整句消化
  if ((mm = m(/^(对手|对方|敌方|自身|自己)(?:精灵)?(?:均|皆)?没有([一-龥]{2,8})$/)) && !/^[将把]/.test(mm[2])) return { not: { markCountAtLeast: { mark: mm[2], n: 1, on: /自身|自己/.test(mm[1]) ? "self" : "foe" } } };
  // "(自身|对手)?未持有X"/"未拥有X"——具名印记缺失（回能Ⅰ/龙鳞等资源名，Ⅰ-Ⅻ 罗马尾缀入名；"红色或白色龙鳞"共享后缀并列名不合并，放走留可审）
  if ((mm = m(/^(自身|自己|对手|对方|敌方)?(?:的)?(?:当前)?(?:未|不)(?:持有|拥有|携带)([一-龥0-9]+[ⅠⅡⅢⅣⅤⅥⅦⅧⅨⅩ]*)$/)) && !/^(?:异常|能力|伤害|体力|护盾|护罩|状态)/.test(mm[2]) && !/或|与|和/.test(mm[2])) return { not: { markCountAtLeast: { mark: mm[2], n: 1, on: /对手|对方|敌方/.test(mm[1] ?? "") ? "foe" : "self" } } };
  // "(对手)被施加的X数量≥N道"已并入 308 通用 markCount（被施加语态+道量词）
  // "(自身|对手)?持有X"/"拥有X"——具名印记持有谓词（"若自身持有回能Ⅰ则…"）
  if ((mm = m(/^(自身|自己|对手|对方|敌方)(?:持有|拥有|携带)([一-龥0-9]+[ⅠⅡⅢⅣⅤⅥⅦⅧⅨⅩ]*)$/)) && !/^(?:异常|能力|伤害|体力|护盾|护罩|状态)/.test(mm[2]) && !/或|与|和/.test(mm[2])) return { markCountAtLeast: { mark: mm[2], n: 1, on: /对手|对方|敌方/.test(mm[1]) ? "foe" : "self" } };
  if (m(/^(?:本回合|当回合|该回合)先手(?:攻击)?$/) ?? m(/^(?:本回合|当回合)先出手$/)) return { order: "first" };
  if (m(/^(?:本方|我方|自身|自己|己方)?先手(?:攻击)?$/) ?? m(/^(?:本方|我方|自身|自己|己方)?先出手$/) ?? m(/^(?:本方|我方|自身|自己|己方)?(?:攻击|物理|特殊|属性)?(?:技能)?先出手$/) ?? m(/^(?:本方|我方|自身|自己|己方)?先出手攻击$/)) return { order: "first" };
  if ((mm = m(/^自身为(?:己方|本方|我方)?最后([一-龥0-9]+)只存活精灵$/)) || (mm = m(/^己方(?:场上)?(?:仅|只)?剩([一-龥0-9]+)只存活精灵$/))) return { benchAliveEq: Math.max(0, num(mm[1]) - 1) };
  if (m(/^(?:本方|自身|自己)?后手(?:攻击)?$/) ?? m(/^后出手$/) ?? m(/^(?:自身|自己)?(?:攻击|物理|特殊|属性)?(?:技能)?后出手$/)) return { order: "last" };
  if (m(/^(?:当回合)?未击败对手$/) ?? m(/^未(?:击杀|击败)(?:对手|对方)$/)) return { not: { foeFainted: true } };
  // "攻击(技能)未击败对手"/"自身使用攻击技能未击败对手" → not foeFainted（攻击方式限定属语境修饰）
  if (m(/^(?:自身|自己)?(?:使用)?(?:攻击|攻击技能|物理攻击|特殊攻击)未(?:曾)?击败(?:对手|对方|敌方)?$/) ?? m(/^自身使用技能未击败对手$/)) return { not: { foeFainted: true } };
  // "受到(的)?攻击伤害高于N"/"每次受到的攻击伤害高于N" → takenAboveAbs（本回合受击阈值——lastTaken 记账）
  if ((mm = m(/^(?:每次)?(?:自身|自己)?受到(?:的)?(?:攻击|攻击伤害|伤害)(?:高于|大于|超过)(\d+)(?:点)?$/))) return { takenAboveAbs: num(mm[1]) };
  // "受到的攻击伤害高于(自身)?最大体力的N/M" → takenAboveHpFrac
  if ((mm = m(new RegExp(`^(?:自身|自己)?受到(?:的)?(?:攻击)?伤害(?:高于|大于|超过)(?:自身|自己)?(?:的)?(?:最大)?体力(?:的)?${NUM}\\s*/\\s*${NUM}$`)))) return { takenAboveHpFrac: frac(mm[1], mm[2]) };
  // "回合结束(时|后)P"——时点修饰叠状态谓词（"若回合结束时自身满体力"——守卫在后续 op 执行时点评估）
  // "回合开始时自身处于能力下降状态"——时点快照谓词（turnStartStages）；须在回合前缀递归剥除之前命中
  if (m(/^(?:在|于)?(?:当|本)?回合开始[时后](?:若)?(?:自身|自己)?处于能力(?:下降|弱化)(?:的)?状态?$/)) return { selfStageDownStart: true };
  if (m(/^(?:在|于)?(?:当|本)?回合开始[时后](?:若)?(?:对手|对方|敌方)处于能力(?:下降|弱化)(?:的)?状态?$/)) return { foeStageDownStart: true };
  if ((mm = m(/^(?:在|于)?回合(?:开始|结束)[时后](.+)$/))) return condOf(mm[1]);
  if (m(/^(?:自身|自己)?(?:为|处于|是)?满体力$/) ?? m(/^自身体力(?:为)?满$/) ?? m(/^(?:自身|自己)?体力值?为?满$/) ?? m(/^(?:出手|攻击)时(?:自身|自己)(?:为|处于|是)?满体力$/)) return { selfHpFull: true };
  if ((mm = m(/^(?:对手|对方|敌方)(?:存在|处于|拥有)(?:护盾|护罩)(?:状态)?$/) ?? m(/^(?:对手|对方|敌方)有(?:护盾|护罩)$/))) return { foeHas: /护罩(?:状态)?$/.test(mm[0]) ? "ward" : "shield" };
  if (m(/^(?:此|该|自身)?护罩(?:存在|尚在|未消失)?$/) ?? m(/^自身(?:存在|处于|已?经?拥有|拥有|持有)护罩(?:状态)?$/) ?? m(/^自身有护罩$/)) return { selfHas: "ward" };
  if (m(/^(?:对手|对方|敌方)(?:存在|处于|已?经?拥有|持有)护罩(?:状态)?$/) ?? m(/^(?:对手|对方|敌方)有护罩$/)) return { foeHas: "ward" };
  if (m(/^自身(?:存在|处于|已经?拥有|拥有|持有)护盾(?:状态)?$/) ?? m(/^自身有护盾$/)) return { selfHas: "shield" };
  if ((mm = m(/^自身不(?:存在|拥有)(?:护盾|护罩)(?:状态)?$/) ?? m(/^自身无(?:护盾|护罩)$/))) return { not: { selfHas: /护罩(?:状态)?$/.test(mm[0]) ? "ward" : "shield" } };
  if ((mm = m(/^(?:对手|对方|敌方)不(?:存在|拥有)(?:护盾|护罩)(?:状态)?$/) ?? m(/^(?:对手|对方|敌方)无(?:护盾|护罩)$/))) return { not: { foeHas: /护罩(?:状态)?$/.test(mm[0]) ? "ward" : "shield" } };
  // "吸取后若对手体力未减少"——上一 op 未造成扣血 → prevDamage==0
  if ((mm = m(/^(?:造成|打出)的?(?:攻击)?伤害若(?:低于|小于|不足)(\d+)(?:点)?$/)) || (mm = m(/^(?:攻击)?伤害若低于(\d+)$/))) return { prevDamageBelowAbs: num(mm[1]) };
  if (m(/^(?:对手|对方|敌方)体力未减少$/) ?? m(/^(?:对手|对方|敌方)体力没有减少$/) ?? m(/^(?:此|该)伤害未减少(?:对手|对方|敌方)?体力$/) ?? m(/^未减少(?:对手|对方|敌方)体力$/)) return { prevDamageBelowAbs: 1 };
  if (m(/^自身未满体力$/) ?? m(/^自身体力未满$/) ?? m(/^若自身未满体力$/) ?? m(/^若?只是未满体力$/) ?? m(/^(?:自身|自己)?(?:体力|HP|生命值?)?不(?:为|是)?满(?:体力|血)?$/)) return { not: { selfHpFull: true } };
  // "对手有高于自身的能力等级"→foeStageAboveSelf（比较谓词）
  if (m(/^(?:对手|对方|敌方)(?:有|存在)?高于自身的能力等级$/) ?? m(/^(?:对手|对方|敌方)能力等级高于自身$/)) return { foeStageAboveSelf: true };
  // "自身所有能力等级均不高于对手"→not selfStageAboveFoe（镜像比较谓词）
  if (m(/^(?:自身|自己)(?:所有|全部|任意)?能力等级(?:均|皆|都)?不高于对手$/) ?? m(/^自身能力不高于对手$/)) return { not: { selfStageAboveFoe: true } };
  // "攻击伤害高于/低于N"（无"造成"裸形——"攻击伤害高于400则X"）
  if ((mm = m(/^攻击(?:技能)?伤害(?:高于|大于|超过)(\d+)(?:点)?$/))) return { prevDamageAboveAbs: num(mm[1]) };
  if ((mm = m(/^攻击(?:技能)?伤害(?:低于|小于|少于|不足)(\d+)(?:点)?$/))) return { prevDamageBelowAbs: num(mm[1]) };
  // "本次（技能）（造成的）伤害低于N"——当次伤害阈
  if ((mm = m(/^本次(?:技能|攻击)?(?:造成的)?伤害(?:低于|小于|少于|不足)(\d+)(?:点)?$/))) return { prevDamageBelowAbs: num(mm[1]) };
  // "自身先制等级大于N"——当前招式基础先制阈（"先制等级大于0时提升为+2"）
  if ((mm = m(/^(?:自身|自己)?先制等级大于(\d+)$/))) return { selfPrioAbove: num(mm[1]) };
  // "造成伤害小于N"→prevDamageBelowAbs（绝对值阈值）
  const dbAbs = s.match(/^(?:若)?造成(?:的)?伤害(?:小于|低于|不足|未超过)(\d+)(?:点)?$/);
  if (dbAbs) return { prevDamageBelowAbs: num(dbAbs[1]) };
  // "受到的攻击伤害低于自身最大体力的N/M"——本回合承伤分数谓词（lastTaken 记账；"自身体力最大"倒装也变体）
  if ((mm = m(new RegExp(`^(?:自身|自己)?受到的?(?:攻击)?伤害低于(?:自身|自己)?(?:最大体力的?|体力最大的?)${NUM}\\s*/\\s*${NUM}$`)))) return { takenBelowHpFrac: frac(mm[1], mm[2]) };
  if ((mm = m(/^(?:自身|自己)?受到的?(?:攻击)?伤害(?:低于|小于|不足|少于)(\d+)(?:点)?$/)) ?? (mm = m(/^(?:当|本)回合(?:自身|自己)?受到的?(?:攻击)?伤害(?:低于|小于|不足|少于)(\d+)(?:点)?$/))) return { takenBelowAbs: num(mm[1]) };
  // "对手体力减少值低于N"——本击对手体力减少量谓词（与 prevDamageBelowAbs 同语义）
  if ((mm = m(/^(?:对手|对方|敌方)体力减少值低于(\d+)(?:点)?$/))) return { prevDamageBelowAbs: num(mm[1]) };
  // "恢复的体力值低于N则X"/"恢复量低于N"——当次 heal 记账谓词（lastHeal）
  if ((mm = m(/^恢复(?:的)?体力(?:值)?(?:低于|少于|不足)(\d+)(?:点)?$/)) ?? (mm = m(/^(?:回复|恢复)(?:量|值)(?:低于|少于|不足)(\d+)(?:点)?$/))) return { prevHealBelow: num(mm[1]) };
  if ((mm = m(/^恢复(?:的)?体力(?:值)?(?:高于|超过|不低于)(\d+)(?:点)?$/)) ?? (mm = m(/^(?:回复|恢复)(?:量|值)(?:高于|超过)(\d+)(?:点)?$/))) return { prevHealAbove: num(mm[1]) };
  // —— 魂印守卫批（soulmark guard batch）——
  // "吸取的体力低于N"/"造成伤害恢复的体力低于N" → prevHealBelow（吸血量作回复量记账）
  if ((mm = m(/^(?:自身|自己)?(?:吸取|吸收)的?(?:体力|HP)(?:值|量)?(?:低于|少于|不足)(\d+)(?:点)?$/))) return { prevHealBelow: num(mm[1]) };
  if ((mm = m(/^造成(?:的)?伤害(?:回复|恢复|转化)的?(?:体力|HP)(?:值|量)?(?:低于|少于|不足)(\d+)(?:点)?$/))) return { prevHealBelow: num(mm[1]) };
  // "造成的伤害不超过/不高于/不大于N" → ≤N → prevDamageBelowAbs(N+1)（整数域精确）
  if ((mm = m(/^(?:自身|自己)?(?:本回合|当回合|本次攻击|攻击|攻击技能)?造成(?:的)?(?:攻击|技能)?伤害(?:不超过|不高于|不大于)(\d+)(?:点)?$/))) return { prevDamageBelowAbs: num(mm[1]) + 1 };
  // "对对手造成伤害超过N"/"伤害大于N" 裸主语/方向变体
  if ((mm = m(/^(?:自身|自己)?对(?:对手|对方|敌方)造成(?:的)?(?:攻击|技能)?伤害(?:高于|大于|超过)(\d+)(?:点)?$/))) return { prevDamageAboveAbs: num(mm[1]) };
  if ((mm = m(/^伤害(?:高于|大于|超过)(\d+)(?:点)?$/))) return { prevDamageAboveAbs: num(mm[1]) };
  // "伤害为N"/"打出的伤害为N" 等值 → and[≥N,≤N]（"本回合自身造成的攻击伤害为N"/"自身攻击技能打出的伤害为N"）
  if ((mm = m(/^(?:(?:本回合|当回合)的?)?(?:自身|自己)?(?:攻击技能)?(?:造成|打出)(?:的)?(?:攻击)?伤害(?:为|等于|恰好为)(\d+)(?:点)?$/))) {
    const v = num(mm[1]);
    return v === 0 ? { not: { prevDamageAboveAbs: 0 } } : { and: [{ prevDamageAboveAbs: v - 1 }, { prevDamageBelowAbs: v + 1 }] };
  }
  // "伤害大于对手体力N/M" 裸"伤害"主语分数（对手的体力=最大基准近似）
  if ((mm = m(new RegExp(`^(?:自身|自己)?(?:造成(?:的)?)?伤害(?:高于|大于|超过)(?:对手|对方|敌方)(?:的)?(?:最大)?体力(?:的)?${NUM}\\s*/\\s*${NUM}(?:时)?$`)))) return { prevDamageAboveFoeFrac: frac(mm[1], mm[2]) };
  // "体力低于当回合开始时的N%" → 回合开始快照分数谓词（turnStartHp 记账）
  if ((mm = m(/^(?:自身|自己)?(?:的)?(?:当前)?(?:体力|HP|生命值)(?:低于|少于|不足|小于)(?:当回合|本回合)?开始时(?:的|体力)?(\d+)%(?:时)?$/))) return { hpBelowTurnStartFrac: { numerator: num(mm[1]), denominator: 100 } };
  // "未造成攻击伤害/未造成伤害" → 无正伤害产出
  if (m(/^(?:自身|自己)?(?:本回合|当回合)?(?:攻击|攻击技能)?未造成(?:攻击)?伤害$/)) return { not: { prevDamageAboveAbs: 0 } };
  // "不触发/本回合未触发" → 前概率项未发动（prevApplied 否定近似）
  if (m(/^(?:(?:当|本)回合)?(?:未|不)触发$/)) return { not: { prevApplied: true } };
  // "对手同时处于A和B" → and[foeHas,foeHas]
  if ((mm = m(new RegExp(`^(对手|对方|敌方)同时(?:已?处于|带有|存在)(${AIL_RE})(?:和|与|及)(${AIL_RE})(?:状态)?$`)))) return { and: [{ foeHas: AILMENTS[mm[2]] }, { foeHas: AILMENTS[mm[3]] }] };
  if ((mm = m(new RegExp(`^(自身|自己)同时(?:已?处于|带有|存在)(${AIL_RE})(?:和|与|及)(${AIL_RE})(?:状态)?$`)))) return { and: [{ selfHas: AILMENTS[mm[2]] }, { selfHas: AILMENTS[mm[3]] }] };
  // "体力高于/低于最大N/M"——裸"最大"后缀（最大体力/最大值的"体力/值"省略形）
  if ((mm = m(new RegExp(`^(?:自身|自己)?(?:的)?(?:当前)?(?:HP|体力值?|生命值|血量)(?:高于|大于|超过)(?:自身|自己)?(?:的)?最大(?:的)?${NUM}\\s*/\\s*${NUM}(?:时)?$`)))) return { selfHpAbove: frac(mm[1], mm[2]) };
  if ((mm = m(new RegExp(`^(?:自身|自己)?(?:的)?(?:当前)?(?:HP|体力值?|生命值|血量)(?:低于|小于|不足|少于)(?:自身|自己)?(?:的)?最大(?:的)?${NUM}\\s*/\\s*${NUM}(?:时)?$`)))) return { selfHpBelow: frac(mm[1], mm[2]) };
  // "当回合未受到攻击伤害"/"未受击"→prevTakenZero
  if (m(/^(?:当|本)?回合(?:自身|自己)?未受到(?:攻击)?伤害$/) ?? m(/^(?:当|本)?回合(?:自身|自己)?未受到(?:攻击|攻击伤害|伤害)$/) ?? m(/^未受到(?:攻击)?伤害$/) ?? m(/^(?:当|本)回合(?:自身|自己)?未受到攻击$/) ?? m(/^未受击$/)) return { prevTakenZero: true };
  if (m(/^(?:当|本)回合(?:自身|自己)?受到(?:的)?(?:攻击|攻击伤害|伤害)$/) ?? m(/^当回合自身受到攻击$/)) return { not: { prevTakenZero: true } };
  if (m(/^触发$/) ?? m(/^触发成功$/) ?? m(/^效果触发$/)) return { prevApplied: true };
  if (m(/^(?:对手|对方|敌方)(?:的)?体力为满$/) ?? m(/^(?:对手|对方|敌方)满体力$/) ?? m(/^(?:对手|对方|敌方)处于满体力(?:状态)?$/)) return { not: { foeHpBelow: { numerator: 1, denominator: 1 } } };
  // "对手未受到攻击伤害"→foeTakenZero（foe.prevTaken===0——关银屏"对手未受到攻击伤害则焚烬"）
  if (m(/^(?:对手|对方|敌方)未受到(?:攻击)?伤害$/) ?? m(/^(?:对手|对方|敌方)未受到攻击$/) ?? m(/^(?:对手|对方|敌方)未受到(?:此|该)伤害$/)) return { foeTakenZero: true };
  // "对手未受到固定/百分比/真实伤害" → prevDamageNotKind（上一 damage 非该类型，无伤害事件也算未受到）
  if ((mm = m(/^(?:若)?(?:对手|对方|敌方)未受到(固定|固伤|百分比|真实)伤害$/))) return { prevDamageNotKind: mm[1] === "固定" || mm[1] === "固伤" ? "fixed" : mm[1] === "百分比" ? "percent" : "true" };
  // "自身不存在/不处于回合类效果" → selfNoTimedFx（回合类=挂在 effects[] 的计时条目）
  if (m(/^(?:自身|自己)?(?:同时)?(?:不存在|不处于|无|没有)回合类效果$/)) return { selfNoTimedFx: true };
  if (m(/^(?:自身|自己)?(?:处于|存在)回合类效果$/)) return { selfHasTimed: true };
  // 裸"不处于能力提升状态"（无主语默认自身侧）
  if (m(/^不处于能力(?:提升|强化|增强)(?:的)?状态?$/) ?? m(/^未处于能力(?:提升|强化|增强)(?:的)?状态?$/)) return { not: { selfStageUp: true } };
  // "受到伤害/受到攻击"裸谓词（"若受到伤害则将伤害反馈"——承伤非零守卫）
  if (m(/^(?:自身|自己)?受到(?:的)?(?:攻击)?伤害$/) ?? m(/^(?:自身|自己)?受到攻击$/)) return { not: { prevTakenZero: true } };
  // "造成(攻击)伤害低于/高于N点"→prevDamageBelowAbs/AboveAbs（攻击阈值守卫——"造成伤害低于300则X"）
  if ((mm = m(/^(?:自身|自己)?(?:攻击技能)?造成(?:的)?(?:攻击)?伤害(?:低于|小于|不足|少于)(\d+)(?:点)?则?$/))) return { prevDamageBelowAbs: num(mm[1]) };
  if ((mm = m(/^(?:自身|自己)?(?:攻击技能)?造成(?:的)?(?:攻击)?伤害(?:高于|大于|超过)(\d+)(?:点)?则?$/))) return { prevDamageAboveAbs: num(mm[1]) };
  // "造成...伤害不低于/不少于N" → not prevDamageBelowAbs（"不低于150"=dmg≥150）
  if ((mm = m(/^(?:自身|自己)?(?:攻击技能)?造成(?:的)?(?:攻击)?伤害(?:不低于|不少于)(\d+)(?:点)?则?$/))) return { not: { prevDamageBelowAbs: num(mm[1]) } };
  // "造成...伤害等于N" → and[not< N, not> N]（"等于750时"=dmg===750）
  if ((mm = m(/^(?:自身|自己)?(?:攻击技能)?造成(?:的)?(?:攻击)?伤害(?:等于|为)(\d+)(?:点)?(?:时|则)?$/))) return { and: [{ not: { prevDamageBelowAbs: num(mm[1]) } }, { not: { prevDamageAboveAbs: num(mm[1]) } }] };
  // "处于X和Y状态"（自身侧复合异常——"处于害怕和冰封则X"）
  if ((mm = m(new RegExp(`^处于(${AIL_RE})和(${AIL_RE})(?:状态)?$`)))) return { and: [{ selfHas: AILMENTS[mm[1]] }, { selfHas: AILMENTS[mm[2]] }] };
  // "<异常>则…"裸谓词（"害怕则吸取对手…"——异常挂在对手侧）
  if (m(/^(?:自身|自己)?(?:击败|击杀|秒杀)(?:对手|对方|敌方)?$/)) return { foeFainted: true };
  if (m(/^(?:自身|自己)?未击败(?:对手|对方|敌方)?$/) ?? m(/^对手未被击败$/) ?? m(/^(?:自身|自己)?攻击未击败(?:对手|对方|敌方)?$/)) return { not: { foeFainted: true } };
  // "未打出致命一击"→非暴击守卫（"攻击未致命一击则消除回合类效果"）
  if (m(/^未(?:打出|造成|触发)?致命[一1]?击?$/) ?? m(/^(?:攻击)?未致命[一1]?击?$/)) return { not: { prevCrit: true } };
  // "双方皆不处于能力提升"→and[非selfStageUp,非foeStageUp]（"敌我双方皆不处于能力提升状态则X"）
  if (m(/^(?:敌我双方|敌我|双方)(?:中|里)?(?:皆|都|均)不处于能力(?:提升|强化)(?:的)?(?:状态)?$/) ?? m(/^(?:敌我双方|敌我|双方)(?:中|里)?(?:皆|都|均)无能力(?:提升|强化)(?:的)?(?:状态)?$/)) return { and: [{ not: { selfStageUp: true } }, { not: { foeStageUp: true } }] };
  // "命中睡眠中的对手"/"对手睡眠中"→foeHas（AIL 作对手修饰语——"攻击命中已处于睡眠状态的对手时附加…"）
  if ((mm = m(new RegExp(`^(?:攻击|攻击技能)?命中(?:已?处于)?(${AIL_RE})(?:状态)?中?的?(?:对手|对方|敌方)(?:时)?$`)))) return { foeHas: AILMENTS[mm[1]] };
  if ((mm = m(new RegExp(`^(?:对手|对方|敌方)(?:已?处于)?(${AIL_RE})中(?:时)?$`)))) return { foeHas: AILMENTS[mm[1]] };
  if ((mm = m(new RegExp(`^(${AIL_RE})(?:状态)?$`)))) return { foeHas: AILMENTS[mm[1]] };
  // "或"复合（"自身处于能力提升状态或对手处于能力下降状态"）——拆分后递归
  const orParts = s.split(/或(?:者)?/);
  if (orParts.length > 1) {
    const subs = orParts.map((p) => condOf(p.trim()));
    if (subs.every((x) => x !== undefined)) return { or: subs };
  }
  // "且/同时/，"复合（"对手处于异常状态且自身处于能力提升状态"/"体力低于对手同时低于最大体力1/3"/"体力低于1/2，自身体力低于对手"）——同法递归 AND
  const andParts = s.split(/且|并且|(?<!相)同时|，|,/); // "相同时"的"同时"是"相同"语素非连词
  if (andParts.length > 1) {
    const subs = andParts.map((p) => condOf(p.trim()));
    if (subs.every((x) => x !== undefined)) return { and: subs };
  }
  if (m(/^(?:对手|对方|敌方)不处于能力(?:提升|增强|强化)(?:状态)?$/) ?? m(/^(?:对手|对方|敌方)无能力(?:提升|强化)状态$/) ?? m(/^(?:对手|对方|敌方)能力不处于(?:提升|增强|强化)(?:状态)?$/)) return { not: { foeStageUp: true } };
