  // "若造成伤害大于对手体力，则留1点血"——条件即 leaveHp 生效域，落地为谓词供 leaveHp 体挂接
  if (m(/^造成(?:的)?伤害大于(?:对手|对方|敌方)(?:的)?(?:当前)?体力(?:值)?$/) ?? m(/^伤害大于(?:对手|对方|敌方)(?:的)?体力(?:值)?$/)) return { dmgGtFoeHp: true };
  // "一方处于X状态"——敌我任一侧持异常（"若有一方处于烧伤状态则必定威力翻倍"）
  if ((mm = m(new RegExp(`^(?:有一方|一方|任一方|双方之一)(?:处于|存在)(${AIL_RE})(?:状态)?$`)))) return { or: [{ selfHas: AILMENTS[mm[1]] }, { foeHas: AILMENTS[mm[1]] }] };
  if (m(/^(?:自身|自己)?(?:当前)?(?:体力|HP|血量)高于对手$/) ?? m(/^自身体力高于对手时$/)) return { selfHpAboveFoe: true };
  if (m(/^(?:未打出|没有打出)致命[一1]?击$/) ?? m(/^本回合未打出致命[一1]?击$/)) return { not: { prevCrit: true } };
  if (m(/^(?:本回合)?打出致命[一1]?击$/)) return { prevCrit: true };
  // "若致命一击则X"——裸"致命一击"=已出暴击谓词
  if (m(/^致命[一1]?击$/)) return { prevCrit: true };
  // "打出的攻击伤害在N-M之间"→lastDealt 区间门（not{dealtBelow:N} ∩ dealtBelow:M+1 数据层等价，零运行时改动）
  if ((mm = m(new RegExp(`^(?:打出|造成)的?攻击?伤害在(${NUM})\\s*[-~～—至到]\\s*(${NUM})之间$`)))) return { and: [{ not: { dealtBelowAbs: num(mm[1]) } }, { dealtBelowAbs: num(mm[3]) + 1 }] };
  // "对手<异常>" / "对手处于<异常>状态" → foeHas
  if ((mm = m(new RegExp(`^(?:对手|对方|敌方)(?:处于|存在)?(${AIL_RE})(?:状态)?$`)))) return { foeHas: AILMENTS[mm[1]] };
  if (m(/^(?:对手|对方|敌方)处于护盾状态$/) ?? m(/^(?:对手|对方|敌方)(?:存在|拥有)护盾$/)) return { foeHas: "shield" };
  // 印记层数谓词（"对手存在处决印记"/"对手致命裂痕≥2层"/"自身存在1层X"）
  if ((mm = m(new RegExp(`^(对手|对方|敌方|自身)(?:当前精灵)?(?:存在|拥有)(.{1,10}?(?:印记|裂痕|圣剑|龙鳞|肃革|伸曲|掩藏|烈岩))[≥＞=]?(\\d+|一|二|两|三|四|五|六|七|八|九|十)?层?$`))))
    return { markCountAtLeast: { mark: mm[2], n: mm[3] !== undefined ? num(mm[3]) : 1, on: /^(对手|对方|敌方)$/.test(mm[1]) ? "foe" : "self" } };
  if (m(/^自身为对手天敌$/) ?? m(/^自身(?:是|为)(?:对手|对方|敌方)的天敌$/)) return { weCounterFoe: true };
