  if (m(/^自身克制(?:对手|对方|敌方)$/) ?? m(/^克制(?:对手|对方|敌方)$/) ?? m(/^自身属性克制(?:对手|对方|敌方)$/)) return { weCounterFoe: true };
  if (m(/^(?:对手|对方|敌方)克制(?:自身|自己)$/) ?? m(/^(?:对手|对方|敌方)克制我方$/)) return { foeCountersUs: true };
  // ── 回合开始快照 ──（turnStartHp/turnStartStages 记账）
  if (m(/^(?:自身|自己)?(?:的)?体力(?:值)?等于当?回合开始(?:时|后|时的体力)?$/) ?? m(/^(?:自身|自己)?体力(?:值)?与当?回合开始(?:时|的体力)?相同$/) ?? m(/^(?:自身|自己)?体力没有变化$/)) return { hpEqTurnStart: true };
  if (m(/^(?:自身|自己)?(?:的)?体力(?:值)?低于当?回合开始(?:时|后|时的体力)?$/) ?? m(/^(?:自身|自己)?体力比当?回合开始时低$/)) return { hpBelowTurnStart: true };
  if (m(/^(?:自身|自己)?(?:的)?体力(?:值)?高于当?回合开始(?:时|后|时的体力)?$/) ?? m(/^(?:自身|自己)?体力比当?回合开始时高$/)) return { hpAboveTurnStart: true };
  // ── 对手体力 vs 自身最大体力分数 ──
  if ((mm = m(new RegExp(`^(?:对手|对方|敌方)(?:的)?体力(?:值)?(?:高于|大于|超过)自身(?:的)?(?:最大)?(?:体力|HP)(?:值)?的?${NUM}\\s*\\/\\s*${NUM}$`)))) return { foeAboveSelfHpFrac: frac(mm[1], mm[2]) };
  if ((mm = m(new RegExp(`^(?:对手|对方|敌方)(?:的)?体力(?:值)?(?:高于|大于|超过)自身(?:的)?(?:最大)?(?:体力|HP)(?:值)?的?(\\d+)%$`)))) return { foeAboveSelfHpFrac: frac(mm[1], "100") };
