  let pendingReact = null; // "则A且B"——跨 clause 延续：且/逗号切出的后续片段并入先前 react 的 payload
  let turnsTail; // 裸时长残段信号（"2回合内"整句被 TURNS_PRE 剥光——无载荷时上交调用层回挂）
  let pendingTurnsTail; // mid-part TURNS_PRE 剥空（"X，2回合内"——时长尾句）——循环后无新增 op 才上交 turnsTail
  let pendingTailAt; // pendingTurnsTail 记录点的效果数——后续 part 产出则该时长是前缀而非尾句
  let effDoubleFlag; // effectDouble 兜底写入的 attachDamage 键名（"scaleIf"/"powerMul"）——跨边界标记幻影源，魂印层挂载成功时可精确删除
  const healEchoQueue = []; // 恢复量反噬延迟 resolve——drain/heal op 可能在后续 clause 才出现
  const floorEchoMarks = []; // "免疫伤害并造成等同于伤害量的固定伤害"尾句标记——回挂最近 dmg_floor
  const downPushMarks = []; // "并反弹给对手"尾句标记——回挂最近 cleanse_down_tick→down_push_tick
  const excessReflectMarks = []; // "并反弹给对手原本超出部分P%"尾句标记——回挂最近 dmg_cap 窗（params.excessPct）
  let prevCtxCond; // 并/且切出的续段继承体级条件（"先出手时恢复A并造成等量固伤"——续段 flatEcho 也受 order 门控）
  let lastPartCond; // part 级条件结转（"消除任意一项成功则X且Y"——Y 也要带"成功"门控；仅记录已产效果的 cond）
