    if (fresh) pendingReact = null;
    // "若X则Y"/"若X，Y"：X 谓词转 Condition 注入整个子句（裸"威力翻倍"→scaleIf）
    let ctxCond = fresh ? undefined : prevCtxCond;
    lastPartCond = undefined;
    let body = clause;
    const cm = clause.match(/^(?:若|如果|本回合若|出手时若|攻击时若|命中时若|给对手造成伤害时若|攻击若|自身攻击若|自身若|自己若|自身使用攻击技能若|自身使用属性技能若|自身使用技能若|使用攻击技能若|使用属性技能若|使用技能若|对手若|对方若)(.+?)(?:，|,|则)(.+)$/) ?? clause.match(/^若(.+?)(当回合.+)$/) ?? clause.match(/^若(.+?(?:状态|异常|提升|强化|下降|满血|满体力))((?:自身|自己|对手|对方|敌方|攻击|命中|下回合|之后|受到|受|使|令|将).+)$/);
