      let m = s.match(/^((?:自身|自己)?(?:当前)?(?:体力|HP|血量)若?(?:高于|大于|低于|小于)对手(?:的)?(?:体力|HP)?)(?:时|则)(.+)$/);
      if (m) { const c = /高于|大于/.test(m[1]) ? { selfHpAboveFoe: true } : { selfHpBelowFoe: true }; return { cond: c, rest: m[2] }; }
      // 无标记粘连："体力大于对手伤害提升N%"/"体力低于对手攻击+1"（动词边界判定防误吞）
