      if (m) { const c = /高于|大于/.test(m[1]) ? { selfHpAboveFoe: true } : { selfHpBelowFoe: true }; return { cond: c, rest: m[2] }; }
      // 分数粘连："体力高于1/2吸取…"/"体力低于1/3恢复…"
      m = s.match(new RegExp(`^((?:自身|自己)?体力(?:高于|大于|超过|低于|小于|少于|不足)${NUM}\\s*/\\s*${NUM})(?=吸取|吸收|恢复|回复|造成|攻击|附加|令|使|全属性|对手|自身)(.+)$`));
      if (m) { const c = /高于|大于|超过/.test(m[1]) ? { selfHpAbove: frac(m[2], m[3]) } : { selfHpBelow: frac(m[2], m[3]) }; return { cond: c, rest: m[4] }; }
      // 耗盾省略谓词："大于300则…"/"小于300且大于0则…"（consumeShield 语境下读护盾消耗量快照，非伤害记账）
      m = s.match(/^(?:若)?(?:消耗(?:的|了)?护[盾罩]值?)?(大于|超过|高于)(\d+)(?:点)?则(.+)$/);
      if (m && effects.some((e) => e.op === "damage" && e.consumeShield === true)) return { cond: { shieldConsumedAbove: num(m[2]) }, rest: m[3] };
      m = s.match(/^(?:若)?(?:消耗(?:的|了)?护[盾罩]值?)?(小于|低于|不足|少于)(\d+)(?:点)?则(.+)$/);
      if (m && effects.some((e) => e.op === "damage" && e.consumeShield === true)) return { cond: { shieldConsumedBelow: num(m[2]) }, rest: m[3] };
