      m = s.match(new RegExp(`^当次攻击击败(${AIL_RE})的(?:对手|对方|敌方)(?:则|时|后|，|,)?(.+)$`));
      if (m && m[2] !== "") return { cond: { and: [{ foeFainted: true }, { foeHas: AILMENTS[m[1]] }] }, rest: m[2] };
      // "异常则Q"——裸异常粘连守卫（攻击语境默认对手侧 statused）
