      m = s.match(/^(若?[^：:]+?)((?:触发|开启|进入|获得)[^：:，,、；;]{1,12}?[：:].+)$/);
      if (m) { const c = condOf(m[1].replace(/^若/, "")); if (c !== undefined) return { cond: c, rest: m[2] }; }
      // "低于N%则Q"/"高于N%则Q"——裸百分比体力粘连守卫
