      m = s.match(/^(高于|大于|超过)(\d+)%(?:时)?则?(.+)$/);
      if (m) return { cond: { selfHpAbove: { numerator: num(m[2]), denominator: 100 } }, rest: m[3] };
      // 通用 "谓词则Y"（"对手体力上限高于1700则伤害提升170%"）：左侧走 condOf；
