        const base = /能力下降/.test(m[0].slice(0, m[1].length)) ? (/(对手|对方|敌方)/.test(who) ? { foeStageDown: true } : { selfStageDown: true }) : /能力提升/.test(m[0].slice(0, m[1].length)) ? (/(对手|对方|敌方)/.test(who) ? { foeStageUp: true } : { selfStageUp: true }) : (/(对手|对方|敌方)/.test(who) ? { foeStatused: true } : { selfStatused: true });
