    // 拆逗号；"、" 仅在左段不以 stat 名结尾时切分（"防御、特防等级-1" 是共享值列表，不切）
    const statTail = new RegExp(`(?:${STAT_RE}|${AIL_RE}|双攻|双防|攻速|双刀|攻防|全属性|所有属性|所有能力)$`);
    // 只续对手侧：自身侧切开后后段本来就落到自身，结果不变
