        const shieldEnum = /护[盾罩]$/.test(cur) && /^护[盾罩](?:值|的|之|类?效果|$)/.test(piece);
        // "能力上升、下降状态"：前段以"能力<方向>"收尾且后段为"X状态"时续接（"消除双方能力上升、下降状态"——切开后裸"下降状态"被 ignored-01 吞，丢失 down 清）
        const abilityEnum = /能力(?:提升|上升|强化|增强|下降|降低)$/.test(cur) && /^(?:下降|降低|提升|上升|强化|增强)(?:的)?状态/.test(piece);
