        const last = merged[merged.length - 1];
        if (last !== undefined && /(?:能力值?|属性|能力)(?:等级)?[-＋+]?\d+$/.test(last) && /^(?:自身|自己)?的?对应的?(?:能力值?|属性|能力)(?:等级)?[+＋+-]?\d+$/.test(p)) merged[merged.length - 1] = `${last}并附加到自身`;
        // "将该属性附加给自己" 镜像尾（被"并"前瞻切碎）——并入前段 transfer_stages 配对
        else if (last !== undefined && /(?:能力值?|属性|能力)(?:等级)?[-＋+]?\d+$/.test(last) && /^并?(?:将|把)?该属?性?(?:能力)?(?:提升|等级)?附加(?:给|到)(?:自己|自身)(?:身上)?$/.test(p)) merged[merged.length - 1] = `${last}并附加到自身`;
