    if (parts.length === 0) parts = [clause];
    if (process.env.PARSE_DEBUG) console.error("[parts]", JSON.stringify(parts));
    let ctxTurns;
    let ctxTurnsRange; // "作用N~M回合" 前缀——随机持续
    const attachAll = [];
    {
      const trm = parts[0]?.match(new RegExp(`^作用${NUM}\\s*[-~～—]\\s*${NUM}回合[，,]?`));
      if (trm) { ctxTurnsRange = { min: num(trm[1]), max: num(trm[2]) }; parts[0] = parts[0].slice(trm[0].length); if (parts[0] === "") parts = parts.slice(1); }
    }
