    let dynTailCond; // 尾置段独立累计（只含最后一个效果之后并入的 cond）
    const mergeDynCond = (c) => { if (dynTailAt !== effects.length) dynTailCond = undefined; dynTailAt = effects.length; dynTailCond = resolveCond(dynTailCond, c); dynCond = resolveCond(dynCond, c); };
    let dynNullify = false; // "技能无效时" 孤儿前缀——后续 part 的效果标 nullifyOnly
