      let nextTgt;
      const nxm = part.match(/^(?:令|使|让)?(对手|对方|敌方|己方|本方|自身)下(?:(?:一|1)?只|个|次)(?:出战|出场|登场)?的?精灵(?:出战时|出场时|登场时|时)?[，,]?(.+)$/) ?? part.match(/^下一个出场的(对手|对方|敌方|己方|本方|自身)(?:精灵)?[，,]?(.+)$/) ?? part.match(/^则?下一个出场的(对手|对方|敌方|己方|本方|自身)(?:精灵)?[，,]?(.+)$/);
      const nxs = part.match(/^(?:令|使|让)?下(?:一个|一只|只|个|次)(?:出战|出场|登场)?的?精灵[，,]?(.+)$/); // 无主语 next-unit（自杀语境 = 己方下只）
      if (nxm) { nextTgt = /^(己方|本方|自身)$/.test(nxm[1]) ? "nextAlly" : "nextFoe"; part = nxm[2].replace(/^的/, "").replace(/^也/, ""); if (part === "") continue; }
      else if (nxs) { nextTgt = "nextAlly"; part = nxs[1].replace(/^的/, ""); if (part === "") continue; }
