      const bcm = part.match(/^(\d+)%(?:的)?(?:概率|几率|机率)?(?=令|使|有|造成|附加|将|受|对|自|提|增|恢|回|降|减|改|吸(?!血)|反(?!馈)|容|易|本|命|攻|免|随|强)/);
